#!/usr/bin/env python3
"""Write the namespace tree for every package generated by the pinned Buf plugin."""

from pathlib import Path

output = Path(__file__).resolve().parent / "src" / "pb"
tree = {}
for package in sorted(output.glob("*.mod.rs")):
    node = tree
    for name in package.name.removesuffix(".mod.rs").split("."):
        node = node.setdefault(name, {})
    node[""] = package.name

if not tree:
    raise SystemExit("No Buffa package modules found; run buf generate first")


def render(node, indent=""):
    lines = []
    for name, child in sorted(node.items()):
        if name == "":
            lines.append(f'{indent}include!("{child}");')
        else:
            # `type` is used by upstream chain packages; raw identifiers preserve
            # the protobuf namespace if such a package is added here later.
            identifier = "r#type" if name == "type" else name
            lines.append(f"{indent}pub mod {identifier} {{")
            lines.extend(render(child, indent + "    "))
            lines.append(f"{indent}}}")
    return lines


(output / "mod.rs").write_text(
    "// @generated by proto/generate-modules.py after buf generate.\n"
    + "\n".join(render(tree))
    + "\n"
)
